import data from "./shots.json";

// srcSet is WebP, avif is the same widths as AVIF, lqip is a 16px data URI placeholder.
export type Shot = { src: string; srcSet: string; avif: string; lqip: string; w: number; h: number; alt?: string };

// cover 16:10, tall 3:4, details 1:1, gallery 16:10. Generated by `npm run shots`.
export type Shots = { cover?: Shot; tall?: Shot; details?: Shot[]; gallery?: Shot[] };

const all: Record<string, Shots> = data;

export const shotsFor = (slug: string): Shots => all[slug] ?? {};
